def split_csv(line):
    fields = []
    field = []
    in_quotes = False
    i = 0
    while i < len(line):
        ch = line[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < len(line) and line[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                field.append(ch)
            i += 1
            continue
        if ch == ',':
            fields.append(''.join(field))
            field = []
        elif ch == '"' and not field:
            in_quotes = True
        else:
            field.append(ch)
        i += 1
    fields.append(''.join(field))
    return fields
